# MAGIC %md
# MAGIC ### Step 3: insert dbo.daily_dispense_summary (T-SQL line 22)

# COMMAND ----------

spark.sql(r"""
WITH dispensed AS (
  SELECT
    d.dispense_date,
    d.patient_id,
    p.therapy_area,
    d.quantity,
    d.days_supply,
    d.billed_amount,
    d.paid_amount
  FROM dbo.dispenses AS d
  INNER JOIN dbo.products AS p
    ON p.product_id = d.product_id
  WHERE
    d.dispense_date = :v_run_date AND d.status = 'DISPENSED'
), by_area AS (
  SELECT
    dispense_date,
    therapy_area,
    COUNT(*) AS dispense_count,
    COUNT(DISTINCT patient_id) AS patient_count,
    SUM(quantity) AS total_quantity,
    SUM(days_supply) AS total_days_supply,
    SUM(billed_amount) AS total_billed,
    SUM(paid_amount) AS total_paid
  FROM dispensed
  GROUP BY
    dispense_date,
    therapy_area
)
INSERT INTO dbo.daily_dispense_summary (
  summary_date,
  summary_date_key,
  therapy_area,
  dispense_count,
  patient_count,
  total_quantity,
  total_days_supply,
  total_billed,
  total_paid,
  paid_to_billed_pct,
  loaded_at
)
SELECT
  dispense_date,
  TRY_CAST(DATE_FORMAT(dispense_date, 'yyyyMMdd') AS CHAR(8)),
  therapy_area,
  dispense_count,
  patient_count,
  total_quantity,
  total_days_supply,
  total_billed,
  total_paid,
  CAST(ROUND(total_paid * 100.0 / NULLIF(total_billed, 0), 2) AS DECIMAL(7, 2)),
  CURRENT_TIMESTAMP()
FROM by_area
""", args={"v_run_date": v_run_date})

